const [liked, setLiked] = useState(post.likedByMe);
const [likes, setLikes] = useState(post.likes);

<ReactionButton
  label={`Like ${post.title}`}
  checked={liked}
  count={likes}
  onChange={(next, n) => {
    setLiked(next); setLikes(n);
    api.like(post.id, next).catch(() => { setLiked(!next); setLikes(likes); });
  }}
/>
